          </table>
        </div>
      )}

      {/* Modals */}
      {showForm && (
        <ClassFormModal
          mode={editItem ? 'edit' : 'add'}
          initial={editItem}
          teachers={teachers}
          onClose={() => { setShowForm(false); setEditItem(null); }}
          onSave={handleSaved}
        />
      )}

      {deleteItem && (
        <ConfirmModal
          item={deleteItem}
          loading={delLoading}
          onConfirm={handleDelete}
          onCancel={() => setDeleteItem(null)}
        />
      )}
    </div>
  );
};

